class Node:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
def find(root, x):
    while root:
        if root.val == x:
            return True
        if x < root.val:
            root = root.left
        else:
            root = root.right
    return False















def zero_one_knapsack(items, W):
    dp = [0] * (W + 1)
    for w, v in items:
        for j in range(W, w - 1, -1):
            dp[j] = max(dp[j], dp[j - w] + v)

    return dp[W]







